    { name: '센텀아트', no: '617-22-36856' },
    { name: '소울필름', no: '621-16-51097' },
    { name: '스카이미디어', no: '504-06-48037' },
    { name: '예일디자인', no: '621-08-19146' },
    { name: '월간좋은세상', no: '617-82-03330' },
    { name: '위컴퍼니', no: '607-20-38703' }
  ];
  for (const item of list) {
    const info = await getBizInfo(item.no);
    console.log(item.name + ' (' + item.no + ') -> 상태: ' + info.status + ' | 법인형태: ' + info.type + ' | 매출: ' + info.revenue);
    await new Promise(r => setTimeout(r, 300));
  }
}
run();
"

